using System;
using System.Linq;
using System.Drawing;
using System.Threading.Tasks;
using System.Windows.Forms;
public class MissionPreset {public int id,width,height,name_id,empire_template,original_population;public string title,note,source_file;public object climate;public bool available=true;public string ClimateText {get{string c=Convert.ToString(climate);return c=="0"?"온화한 기후":c=="1"?"북부 기후":c=="2"?"사막 기후":c;}}public string PopulationNotice {get{return note!=null?note:original_population>0?"기존 주민 "+original_population.ToString("N0")+"명 · 원본 건물은 유지됩니다.":"원본 지형·건물은 유지하고 미션 진행은 초기화합니다.";}}public override string ToString(){if(id<0)return title+(width>0?"  ("+width+"×"+height+")":"")+"  · "+Lang.T("가져온 지도");return title+"  ("+width+"×"+height+")"+(original_population>0?" · 주민 "+original_population.ToString("N0")+"명":"");}}
public class EmpirePreset {public int id;public string title;public override string ToString(){return title;}}
public class PresetCatalog {public MissionPreset[] terrain;public EmpirePreset[] empire;}
public class EmpirePresetResult {public int template;public City[] cities;}
public class CreatorPresetPicker : Form {
 readonly System.Collections.Generic.List<MissionPreset> presets;readonly Func<int,TerrainData> loader;readonly int current;
 ListBox list=new ListBox{Dock=DockStyle.Fill,IntegralHeight=false};TextBox search=new TextBox{Dock=DockStyle.Fill};
 ComboBox kind=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};
 CreatorTerrainView preview=new CreatorTerrainView{ReadOnly=true,ShowProtected=false};Label details=new Label{Dock=DockStyle.Fill};
 Button apply=new Button{Text="이 지형 사용",Width=150,Height=34,Enabled=false};int request;
 public MissionPreset SelectedPreset {get{return list.SelectedItem as MissionPreset;}}
 // importer/remover (2026-11-15): the city's brought-in maps (ids < 0) can be added and taken off the list here; current is marked.
 public CreatorPresetPicker(MissionPreset[] items,int selected,Func<int,TerrainData> load,bool synchronousPreview=false,Func<MissionPreset> importer=null,Func<MissionPreset,bool> remover=null,int current=int.MinValue){
  presets=items.Where(p=>p.available).ToList();loader=load;this.current=current;Text="도시 지형 선택";Font=new Font("Malgun Gothic",9);ClientSize=new Size(1080,720);MinimumSize=new Size(900,600);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(236,223,193);ForeColor=Color.FromArgb(40,35,29);
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=3,Padding=new Padding(12)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,310));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,58));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,58));Controls.Add(root);
  var filter=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};filter.Controls.Add(search,0,0);filter.Controls.Add(kind,0,1);kind.Items.AddRange(new object[]{"모든 지형","캠페인 지형","공식 자유 건설 지도","가져온 지도"});kind.SelectedIndex=0;root.Controls.Add(filter,0,0);root.Controls.Add(list,0,1);root.Controls.Add(details,1,0);root.Controls.Add(preview,1,1);
  var foot=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var cancel=new Button{Text="취소",Width=100,Height=34,DialogResult=DialogResult.Cancel};foot.Controls.Add(cancel);foot.Controls.Add(apply);
  if(importer!=null){var add=new Button{Text="지도 파일 가져오기",Width=150,Height=34};add.Click+=(s,e)=>{try{var p=importer();if(p==null)return;presets.RemoveAll(x=>x.id==p.id);presets.Add(p);kind.SelectedIndex=0;search.Text="";Filter(p.id);}catch(Exception error){LangBox.Show(this,error.Message,"지도 가져오기",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};foot.Controls.Add(add);}
  if(remover!=null){var drop=new Button{Text="목록에서 빼기",Width=130,Height=34};drop.Click+=(s,e)=>{var p=SelectedPreset;if(p==null||p.id>=0){LangBox.Show(this,"가져온 지도만 목록에서 뺄 수 있습니다.","지도 목록",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}if(p.id==this.current){LangBox.Show(this,"지금 쓰는 지도는 뺄 수 없습니다. 다른 지형을 먼저 고르세요.","지도 목록",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}if(remover(p)){presets.Remove(p);Filter(this.current);}};foot.Controls.Add(drop);}
  list.FormattingEnabled=true;list.Format+=(s,e)=>{var p=e.ListItem as MissionPreset;if(p!=null&&p.id==this.current)e.Value="["+Lang.T("사용 중")+"] "+Lang.T(Convert.ToString(p));};foot.Controls.Add(new Label{Text="원본의 목표·침략·황제 요구 등 미션 진행은 새 시나리오로 가져오지 않습니다.",AutoSize=true,Padding=new Padding(4,8,8,0)});root.Controls.Add(foot,0,2);root.SetColumnSpan(foot,2);CancelButton=cancel;AcceptButton=apply;apply.Click+=(s,e)=>{if(SelectedPreset!=null){DialogResult=DialogResult.OK;Close();}};list.SelectedIndexChanged+=async(s,e)=>{if(synchronousPreview)PreviewSync();else await Preview();};search.TextChanged+=(s,e)=>Filter(selected);kind.SelectedIndexChanged+=(s,e)=>Filter(selected);Filter(selected);
 }
 void Filter(int wanted){var previous=SelectedPreset;if(previous!=null)wanted=previous.id;list.BeginUpdate();list.Items.Clear();foreach(var p in presets.Where(p=>(kind.SelectedIndex==0||kind.SelectedIndex==1&&p.id>=0&&p.id<100||kind.SelectedIndex==2&&p.id>=100||kind.SelectedIndex==3&&p.id<0)&&(search.Text.Trim().Length==0||p.title.IndexOf(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0)))list.Items.Add(p);list.EndUpdate();for(int i=0;i<list.Items.Count;i++)if(((MissionPreset)list.Items[i]).id==wanted){list.SelectedIndex=i;return;}if(list.Items.Count>0)list.SelectedIndex=0;else{apply.Enabled=false;details.Text="조건에 맞는 지형이 없습니다.";}}
 void PreviewSync(){var p=SelectedPreset;if(p==null)return;var data=loader(p.id);preview.Bind(data,new TerrainEdit[0]);details.Text=p.title+"  ·  "+data.width+"×"+data.height+"  ·  "+p.ClimateText+"\n"+p.PopulationNotice;apply.Enabled=true;}
 async Task Preview(){int version=++request;apply.Enabled=false;var p=SelectedPreset;if(p==null)return;details.Text=p.title+"  ·  "+p.width+"×"+p.height+"  ·  "+p.ClimateText+"\n실제 도시 지형을 읽고 있습니다…";try{var data=await Task.Run(()=>loader(p.id));if(IsDisposed||version!=request)return;preview.Bind(data,new TerrainEdit[0]);details.Text=p.title+"  ·  "+data.width+"×"+data.height+"  ·  "+p.ClimateText+"\n"+p.PopulationNotice;apply.Enabled=true;}catch(Exception e){if(!IsDisposed&&version==request)details.Text="지형을 읽지 못했습니다. "+e.Message;}}
}
